require_once '../config.php';requireAdmin();$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT o.*,u.name customer,u.email FROM orders o JOIN users u ON u.id=o.user_id WHERE o.id=?");$s->execute([$id]);$order=$s->fetch();if(!$order)exit('Pedido não encontrado.');$s=$pdo->prepare("SELECT oi.*,p.name FROM order_items oi JOIN products p ON p.id=oi.product_id WHERE oi.order_id=?");$s->execute([$id]);$items=$s->fetchAll();$pageTitle='Detalhes do pedido';include '../includes/header.php';?>
<div class="page-head"><div class="container"><div class="section-kicker">CENTRAL DE COMANDO</div><h1>PEDIDO #<?= $id ?></h1></div></div><section class="section"><div class="container"><div class="dark-panel"><p>Cliente: <strong><?= e($order['customer']) ?></strong> (<?= e($order['email']) ?>)</p><p>Data: <?= date('d/m/Y H:i',strtotime($order['created_at'])) ?> • Pagamento: <?= e($order['payment_method']) ?></p><div class="table-responsive"><table class="table table-dark"><thead><tr><th>Produto</th><th>Quantidade</th><th>Preço unitário</th><th>Subtotal</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?= e($i['name']) ?></td><td><?= $i['quantity'] ?></td><td><?= money($i['unit_price']) ?></td><td><?= money($i['quantity']*$i['unit_price']) ?></td></tr><?php endforeach; ?></tbody></table></div><h3 class="text-end">Total: <?= money($order['total']) ?></h3><a class="btn-outline" href="index.php">VOLTAR</a></div></div></section><?php include '../includes/footer.php'; ?>
